:root {
  color-scheme: dark;
}

html,
body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  place-items: center;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 760px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  min-width: 0;
  padding: 18px 18px 16px;
  display: grid;
  gap: 16px;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.label {
  font-size: 13px;
  color: #9ca3af;
}

.source,
.status-filter {
  background: #0f172a;
  color: #e5e7eb;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 6px 8px;
  font: inherit;
}

.refresh,
.fail-next,
.retry,
.retry-delivery {
  background: #1e293b;
  color: #e5e7eb;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 6px 10px;
  font: inherit;
  cursor: pointer;
}

.refresh:disabled,
.retry-delivery:disabled {
  opacity: 0.5;
  cursor: default;
}

.status-line {
  min-height: 22px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
}

.status--loading {
  color: #93c5fd;
}

.status--error {
  color: #fca5a5;
}

.empty,
.count,
.skipped {
  color: #9ca3af;
}

.table-scroll {
  position: relative;
  overflow-x: auto;
}

.deliveries {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.deliveries th,
.deliveries td {
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid #1f2937;
}

.endpoint {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 13px;
  word-break: break-all;
}

.status {
  text-transform: capitalize;
}

.status--delivered {
  color: #86efac;
}

.status--failed {
  color: #fca5a5;
}

.status--pending {
  color: #fcd34d;
}

@media (max-width: 520px) {
  .toolbar {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
  }

  .deliveries {
    min-width: 560px;
  }

  .endpoint {
    word-break: normal;
    white-space: nowrap;
  }
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
